const ToastContext = createContext<(message: string, tone?: Toast['tone']) => void>(() => undefined);
const useNotify = () => useContext(ToastContext);

function ToastStack({ toasts, dismiss }: { toasts: Toast[]; dismiss: (id: number) => void }) {
  return (
    <div className="fixed bottom-5 right-5 z-[120] flex w-[min(360px,calc(100vw-40px))] flex-col gap-2">
      {toasts.map((item) => (
        <button key={item.id} type="button" onClick={() => dismiss(item.id)} data-testid={`toast-${item.id}`} className="glass flex items-center gap-3 rounded-2xl px-4 py-3 text-left text-sm shadow-2xl">
          <span className={`grid h-7 w-7 shrink-0 place-items-center rounded-full ${item.tone === 'success' ? 'bg-[#91eff1]/15 text-[#91eff1]' : 'bg-[#d4a2ff]/15 text-[#d4a2ff]'}`}>
            {item.tone === 'success' ? <Check size={15} /> : <Sparkles size={15} />}
          </span>
          <span className="flex-1 text-[#ede6f6]">{item.message}</span><X size={14} className="text-[#8d849d]" />
        </button>
      ))}
    </div>
  );
}

