function PageTitle({ eyebrow, title, copy, action }: { eyebrow: string; title: ReactNode; copy?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><div className="mb-2 flex items-center gap-2 text-[10px] font-semibold uppercase tracking-[.22em] text-[#a17ac1]"><span className="h-px w-5 bg-[#a17ac1]" />{eyebrow}</div><h1 className="text-[clamp(2rem,4vw,3.15rem)] font-extrabold leading-[1.03] tracking-[-.06em] text-[#f2eaf7]">{title}</h1>{copy && <p className="mt-3 max-w-xl text-[13px] leading-6 text-[#9f95aa]">{copy}</p>}</div>{action}</div>;
}

function GlassCard({ children, className = '', ...props }: { children: ReactNode; className?: string; [key: string]: unknown }) {
  return <section className={`glass rounded-2xl ${className}`} {...props}>{children}</section>;
}

function ProgressBar({ value, color = 'linear-gradient(90deg,#d19bff,#8fe8eb)' }: { value: number; color?: string }) {
  return <div className="h-1.5 overflow-hidden rounded-full bg-white/[.09]" role="progressbar" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100} data-testid="progress-bar"><div className="h-full rounded-full transition-all duration-300" style={{ width: `${value}%`, background: color }} /></div>;
}

function Modal({ open, title, children, onClose }: { open: boolean; title: string; children: ReactNode; onClose: () => void }) {
  if (!open) return null;
  return <div className="fixed inset-0 z-[110] grid place-items-center bg-[#08060d]/70 px-5 backdrop-blur-md" role="dialog" aria-modal="true" aria-label={title}><div className="glass w-full max-w-md rounded-2xl p-5 shadow-2xl sm:p-7"><div className="flex items-center justify-between"><h2 className="text-[15px] font-semibold text-[#f0e6f4]">{title}</h2><button type="button" onClick={onClose} data-testid="button-close-modal" className="grid h-8 w-8 place-items-center rounded-lg text-[#91859b] hover:bg-white/[.07] hover:text-[#ead5f2]"><X size={15} /></button></div>{children}</div></div>;
}

function StatTile({ label, value, change, color }: { label: string; value: string; change: string; color: string }) {
  return <GlassCard className="p-5"><div className="flex items-start justify-between"><span className="text-[11px] text-[#92869d]">{label}</span><span className="h-2 w-2 rounded-full" style={{ background: color, boxShadow: `0 0 16px ${color}` }} /></div><div className="mt-5 text-[25px] font-semibold tracking-[-.06em] text-[#f1e8f4]" data-testid={`text-stat-${label.toLowerCase().replaceAll(' ', '-')}`}>{value}</div><div className="mt-1 flex items-center gap-1 text-[10px] text-[#8de3e7]"><ArrowDownRight size={12} className="rotate-180" />{change} <span className="text-[#756b7e]">vs last month</span></div></GlassCard>;
}

function Thumbnail({ gradient, title, duration, large = false }: { gradient: string; title?: string; duration?: string; large?: boolean }) {
  return <div className={`group relative overflow-hidden rounded-xl ${large ? 'aspect-[16/9]' : 'aspect-[1.46/1]'}`} style={{ background: gradient }}><div className="absolute inset-0 bg-[radial-gradient(circle_at_72%_22%,rgba(255,255,255,.45),transparent_14%),linear-gradient(120deg,transparent,rgba(0,0,0,.32))]" /><div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-[#090711]/70 to-transparent" /><div className="absolute bottom-3 left-3 right-3 flex items-end justify-between">{title && <span className="max-w-[76%] truncate text-[11px] font-semibold text-white">{title}</span>}{duration && <span className="rounded-md bg-black/35 px-1.5 py-1 font-mono text-[9px] text-white/80">{duration}</span>}</div></div>;
}

function ProjectCard({ project, compact = false }: { project: typeof projects[number]; compact?: boolean }) {
  const notify = useNotify();
  return <GlassCard className={`group overflow-hidden ${compact ? '' : 'p-2'}`} data-testid={`card-project-${project.id}`}><div className={compact ? '' : ''}><Thumbnail gradient={project.gradient} title={compact ? undefined : project.title} duration={project.duration} /></div><div className="flex items-center justify-between gap-3 px-2 py-3"><div className="min-w-0"><div className="truncate text-[12px] font-semibold text-[#e9e0ef]" data-testid={`text-project-title-${project.id}`}>{project.title}</div><div className="mt-1 flex items-center gap-2 text-[10px] text-[#8e839a]"><span>{project.style}</span><span className="h-0.5 w-0.5 rounded-full bg-[#675e70]" /><span>{project.time}</span></div></div><button type="button" onClick={() => notify(`${project.title} opened in preview.`, 'success')} data-testid={`button-open-project-${project.id}`} className="grid h-7 w-7 shrink-0 place-items-center rounded-lg text-[#9a8da4] opacity-0 transition group-hover:opacity-100 hover:bg-white/[.08] hover:text-[#f3d8ff]"><MoreHorizontal size={16} /></button></div></GlassCard>;
}

function StepRail({ current, setCurrent }: { current: number; setCurrent: (step: number) => void }) {
  const steps = ['Upload', 'Trend', 'Generate', 'Preview'];
  return <div className="mb-8 flex w-full items-center overflow-x-auto pb-1 hide-scrollbar">{steps.map((step, i) => { const number = i + 1; const done = number < current; return <div key={step} className="flex min-w-[112px] flex-1 items-center"><button type="button" onClick={() => (number <= current ? setCurrent(number) : undefined)} data-testid={`button-step-${number}`} className={`flex items-center gap-2 text-[11px] ${number === current ? 'font-semibold text-[#eee4f4]' : done ? 'text-[#b5a6c1]' : 'text-[#655c6d]'}`}><span className={`grid h-7 w-7 place-items-center rounded-full border text-[10px] ${number === current ? 'border-[#dfa7ff] bg-[#dca4ff]/15 text-[#e2b5ff]' : done ? 'border-[#8fe8eb]/60 bg-[#8fe8eb]/10 text-[#91e9eb]' : 'border-white/[.13]'}`}>{done ? <Check size={13} /> : `0${number}`}</span>{step}</button>{number < steps.length && <span className={`mx-3 h-px flex-1 ${done ? 'bg-[#8fe8eb]/45' : 'bg-white/[.1]'}`} />}</div>; })}</div>;
}

function ReferenceStyleCard({ style, selected, onSelect }: { style: typeof styles[number]; selected: boolean; onSelect: () => void }) {
  const [referenceName, setReferenceName] = useState('');
  const notify = useNotify();
  const addReference = (file?: File) => { if (!file) return; setReferenceName(file.name); notify(`Reference video added to ${style.name}.`, 'success'); };
  return <div role="button" tabIndex={0} onClick={onSelect} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') onSelect(); }} data-testid={`reference-style-${style.id}`} className={`group relative overflow-hidden rounded-2xl border text-left transition duration-300 hover:-translate-y-1 ${selected ? 'border-[#dda6ff] shadow-[0_0_0_2px_rgba(221,166,255,.16),0_18px_40px_rgba(151,77,208,.18)]' : 'border-white/[.1] hover:border-white/[.25]'}`}><div className="relative aspect-[1.26/1]" style={{ background: style.gradient }}><div className="absolute inset-0 bg-[linear-gradient(135deg,rgba(0,0,0,.05),rgba(0,0,0,.44))]" /><label onClick={(event) => event.stopPropagation()} className="absolute left-4 top-4 flex cursor-pointer items-center gap-1.5 rounded-lg border border-white/20 bg-black/20 px-2 py-1.5 text-[9px] font-semibold text-white backdrop-blur-sm transition hover:bg-black/35" title="Upload your own reference video"><input type="file" accept="video/*" className="hidden" onChange={(event) => addReference(event.target.files?.[0])} data-testid={`input-reference-${style.id}`} />{referenceName ? <Check size={12} className="text-[#91e9eb]" /> : <UploadCloud size={12} />}{referenceName ? 'Added' : 'Add video'}</label>{selected && <span className="absolute right-3 top-3 grid h-6 w-6 items-center justify-center rounded-full bg-[#e6b6ff] text-[#24112d]"><Check size={14} /></span>}<div className="absolute bottom-4 left-4 right-4"><div className="mb-1 text-[10px] uppercase tracking-[.18em] text-white/60">{style.type}</div><div className="text-[17px] font-semibold tracking-[-.04em] text-white">{style.name}</div></div></div><div className="bg-[#191421] p-4"><p className="min-h-[36px] text-[11px] leading-5 text-[#a99dad]">{referenceName ? `${referenceName} is ready as your reference.` : style.description}</p><div className="mt-3 flex items-center justify-between text-[9px] text-[#766c80]"><span>{referenceName ? 'Your reference' : style.tag}</span><span>{style.stat}</span></div></div></div>;
}

