function NotFoundPage() {
  return <div className="grid min-h-[70vh] place-items-center"><div className="text-center"><div className="font-mono text-[10px] uppercase tracking-[.24em] text-[#a17ac1]">Frame not found</div><h1 className="mt-4 text-4xl font-semibold tracking-[-.06em] text-[#f0e6f4]">This cut got lost.</h1><p className="mt-3 text-sm text-[#93889c]">Let’s get you back to the studio.</p><Link href="/" data-testid="link-not-found-home" className="mt-6 inline-flex rounded-xl bg-[#e9dff0] px-4 py-3 text-[11px] font-bold text-[#201525]">Back to overview</Link></div></div>;
}

function CreateStudioPage() {
  const notify = useNotify();
  const [stage, setStage] = useState(1);
  const [fileName, setFileName] = useState('');
  const [progress, setProgress] = useState(0);
  const [selectedStyle, setSelectedStyle] = useState(styles[0]);
  const [generating, setGenerating] = useState(false);
  const goToTrends = () => {
    if (!fileName || progress < 100) {
      notify('Add a complete upload before choosing a trend.', 'info');
      return;
    }
    setStage(2);
  };
  const generate = () => {
    setGenerating(true);
    setStage(3);
    notify('StyleCut is finding the rhythm in your footage.', 'info');
    window.setTimeout(() => {
      setGenerating(false);
      setStage(4);
      notify('Your first cut is ready to preview.', 'success');
    }, 2800);
  };
  return <div className="float-in">
    <PageTitle eyebrow="Create studio" title={<>Turn raw footage<br /><span className="text-gradient">into a point of view.</span></>} copy="Four deliberate steps. Your footage, your trend, your cut." action={<div className="flex items-center gap-2 text-[10px] text-[#8f849a]"><LockKeyhole size={13} /> Local demo workspace</div>} />
    <StepRail current={stage} setCurrent={setStage} />
    {stage === 1 && <div className="grid gap-5 xl:grid-cols-[1.4fr_.6fr]"><GlassCard className="p-5 sm:p-7"><div className="mb-5 flex items-start justify-between"><div><h2 className="text-[15px] font-semibold text-[#eee5f3]">Upload raw footage</h2><p className="mt-1 text-[11px] text-[#8f8498]">Start with the uncut version. We’ll find the story inside it.</p></div><span className="rounded-lg border border-[#8fe8eb]/20 bg-[#8fe8eb]/[.06] px-2 py-1 font-mono text-[9px] text-[#8fe8eb]">01 / 04</span></div><UploadDropzone fileName={fileName} setFileName={setFileName} progress={progress} setProgress={setProgress} /><div className="mt-5 flex justify-end"><button type="button" onClick={goToTrends} data-testid="button-next-trends" className="inline-flex items-center gap-2 rounded-xl bg-[#e9dff0] px-4 py-3 text-[11px] font-bold text-[#201525] hover:bg-white">Choose a trend <ArrowRight size={14} /></button></div></GlassCard><GlassCard className="p-6"><div className="flex items-center gap-2 text-[10px] uppercase tracking-[.18em] text-[#a37abf]"><Gauge size={14} /> Good to know</div><div className="mt-6 space-y-5">{[['01', 'Keep it honest', 'Long takes give the AI more texture to work with.'], ['02', 'Sound matters', 'Clean audio helps us find the cut points that feel human.'], ['03', 'Vertical wins', 'We’ll frame the output for 9:16 by default.']].map(([number, title, copy]) => <div key={number} className="flex gap-3"><span className="font-mono text-[10px] text-[#7d7189]">{number}</span><div><div className="text-[12px] font-semibold text-[#d9ccdf]">{title}</div><p className="mt-1 text-[10px] leading-4 text-[#867b8f]">{copy}</p></div></div>)}</div></GlassCard></div>}
    {stage === 2 && <div className="grid gap-5 xl:grid-cols-[1fr_390px]"><GlassCard className="p-5 sm:p-7"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-[15px] font-semibold text-[#eee5f3]">Choose a trend</h2><p className="mt-1 text-[11px] text-[#8f8498]">{fileName || 'Your footage'} · 04:18 · 42 MB</p></div><button type="button" onClick={() => setStage(1)} data-testid="button-back-upload" className="text-[11px] text-[#9e91ab] hover:text-[#ddb1ff]">Back to upload</button></div><div className="grid gap-4 sm:grid-cols-2">{styles.map((style) => <ReferenceStyleCard key={style.id} style={style} selected={selectedStyle.id === style.id} onSelect={() => setSelectedStyle(style)} />)}</div><div className="mt-6 flex justify-end"><button type="button" onClick={generate} data-testid="button-generate-edit" className="group inline-flex items-center gap-2 rounded-xl bg-[#dca4ff] px-4 py-3 text-[11px] font-bold text-[#190d20] shadow-[0_8px_30px_rgba(210,150,255,.2)] hover:bg-[#e7baff]">Generate my edit <Sparkles size={14} className="transition group-hover:rotate-12" /></button></div></GlassCard><ChatAssistant /></div>}
    {stage === 3 && <GlassCard className="relative min-h-[520px] overflow-hidden p-6 sm:p-12"><div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_38%,rgba(194,124,255,.13),transparent_35%)]" /><div className="relative z-10 mx-auto flex max-w-lg flex-col items-center text-center"><div className="relative grid h-24 w-24 place-items-center rounded-[28px] border border-[#d9a6ff]/30 bg-[#dca4ff]/10 text-[#dfa6ff] shadow-[0_0_80px_rgba(201,124,255,.18)]"><div className="absolute inset-[-9px] rounded-[34px] border border-[#8fe8eb]/20" /><WandSparkles size={32} strokeWidth={1.3} /></div><div className="mt-8 text-[10px] uppercase tracking-[.22em] text-[#9e7db4]">{generating ? 'Building your first cut' : 'Generation complete'}</div><h2 className="mt-3 text-3xl font-semibold tracking-[-.06em] text-[#f2e9f6]">{generating ? 'Finding the pulse.' : 'Your cut is ready.'}</h2><p className="mt-3 text-[12px] leading-6 text-[#94899e]">{generating ? 'Scanning your footage for movement, meaning, and the frame before the frame.' : 'We found the thread. Take a look, then make it yours.'}</p>{generating && <div className="mt-10 w-full"><div className="mb-2 flex justify-between text-[10px] text-[#897d93]"><span>Assembling moments</span><span className="font-mono text-[#dba8ff]">LIVE</span></div><div className="h-1.5 overflow-hidden rounded-full bg-white/[.08]"><div className="sweep h-full w-1/3 rounded-full bg-[linear-gradient(90deg,transparent,#dca4ff,#8fe8eb,transparent)]" /></div><div className="mt-9 grid grid-cols-3 gap-2">{['Reading clips', 'Mapping the beat', 'Balancing color'].map((item, i) => <div key={item} className="rounded-xl border border-white/[.08] bg-white/[.03] p-3 text-[10px] text-[#b2a5ba]"><span className="mb-2 block font-mono text-[9px] text-[#8fe8eb]">0{i + 1}</span>{item}</div>)}</div></div>}</div></GlassCard>}
    {stage === 4 && <div className="grid gap-5 xl:grid-cols-[1.18fr_.82fr]"><GlassCard className="overflow-hidden p-3 sm:p-4"><div className="relative aspect-[9/12] max-h-[600px] overflow-hidden rounded-xl bg-[linear-gradient(140deg,#171020,#774a9c_42%,#ee76b8)]"><div className="absolute inset-0 bg-[radial-gradient(ellipse_at_68%_26%,rgba(255,255,255,.74),transparent_4%),radial-gradient(ellipse_at_30%_55%,rgba(9,5,20,.8),transparent_35%),linear-gradient(130deg,transparent,rgba(8,3,15,.35))]" /><div className="absolute left-5 top-5 rounded-md border border-white/20 bg-black/20 px-2 py-1 font-mono text-[9px] text-white/80">STYLECUT / 01</div><button type="button" onClick={() => notify('Cinema mode opened.', 'success')} data-testid="button-play-result" className="absolute left-1/2 top-1/2 grid h-16 w-16 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full border border-white/35 bg-white/15 text-white backdrop-blur-md transition hover:scale-105"><Play size={22} fill="currentColor" /></button><div className="absolute inset-x-5 bottom-5"><div className="mb-3 text-right font-mono text-[10px] text-white/75">00:42 / 00:42</div><div className="h-1 overflow-hidden rounded-full bg-white/25"><div className="h-full w-full bg-white" /></div><div className="mt-3 flex items-center justify-between text-[10px] text-white/75"><span>{selectedStyle.name} / first pass</span><span className="flex items-center gap-1"><Volume2 size={12} /> 84%</span></div></div></div><div className="flex flex-wrap items-center justify-between gap-3 px-1 pt-4"><div><div className="text-[13px] font-semibold text-[#eee5f3]">The city is still awake</div><div className="mt-1 text-[10px] text-[#8e8297]">First pass · 9:16 · 1080 × 1920</div></div><div className="flex gap-2"><button type="button" onClick={() => notify('Download queued for your local demo.', 'success')} data-testid="button-download-result" className="grid h-9 w-9 place-items-center rounded-lg border border-white/[.11] text-[#bbb0c4] hover:bg-white/[.07]"><Download size={15} /></button><button type="button" onClick={() => notify('Share link copied to clipboard.', 'success')} data-testid="button-share-result" className="grid h-9 w-9 place-items-center rounded-lg border border-white/[.11] text-[#bbb0c4] hover:bg-white/[.07]"><Share2 size={15} /></button></div></div></GlassCard><div className="space-y-5"><GlassCard className="p-5"><div className="flex items-center justify-between"><h2 className="text-[13px] font-semibold text-[#eee5f3]">Before / after</h2><Eye size={15} className="text-[#9b8da5]" /></div><div className="mt-4 grid grid-cols-2 gap-2"><div><div className="aspect-[9/12] rounded-lg bg-[linear-gradient(145deg,#343038,#726975)]" /><div className="mt-2 text-[9px] uppercase tracking-[.16em] text-[#81758b]">Raw</div></div><div><div className="aspect-[9/12] rounded-lg bg-[linear-gradient(145deg,#1a1023,#8c50a6_48%,#eb82bb)]" /><div className="mt-2 text-[9px] uppercase tracking-[.16em] text-[#d6a4e9]">Edited</div></div></div><div className="mt-5 space-y-3">{[['Scored moments', '14 / 84 clips'], ['Captions', 'Ready'], ['Trend', selectedStyle.name]].map(([label, value]) => <div key={label} className="flex items-center justify-between border-t border-white/[.07] pt-3 text-[10px]"><span className="text-[#887d92]">{label}</span><span className="text-[#d6cadf]">{value}</span></div>)}</div></GlassCard><GlassCard className="p-5"><div className="flex items-center gap-2 text-[11px] font-semibold text-[#e8deef]"><Sparkles size={14} className="text-[#dca4ff]" /> Make it yours</div><div className="mt-4 grid grid-cols-2 gap-2"><button type="button" onClick={() => setStage(2)} data-testid="button-adjust-result" className="rounded-lg border border-white/[.1] px-3 py-2.5 text-[10px] text-[#b6a8bd] hover:bg-white/[.06]">Choose another trend</button><button type="button" onClick={() => notify('Version 01 saved to Projects.', 'success')} data-testid="button-save-result" className="rounded-lg bg-[#dca4ff] px-3 py-2.5 text-[10px] font-bold text-[#1b1022] hover:bg-[#e7baff]">Save version</button></div></GlassCard></div></div>}
  </div>;
}

function TrendsPage() {
  const [filter, setFilter] = useState('All trends');
  const filtered = useMemo(() => filter === 'All trends' ? styles : styles.filter((style) => style.type.includes(filter)), [filter]);
  return <div className="float-in"><PageTitle eyebrow="Trends" title={<>Find the feeling<br /><span className="text-gradient">before the first cut.</span></>} copy="Browse editing directions, then upload your own reference video to teach StyleCut the language you want." action={<Link href="/create" data-testid="link-trends-create" className="inline-flex items-center gap-2 rounded-xl bg-[#dca4ff] px-4 py-3 text-[11px] font-bold text-[#190d20] hover:bg-[#e7baff]"><Plus size={14} /> Create with a trend</Link>} />
    <div className="mb-6 flex gap-2 overflow-x-auto pb-1 hide-scrollbar">{['All trends', 'Cinematic', 'Lifestyle', 'Fast / Raw', 'Editorial'].map((item) => <button type="button" key={item} onClick={() => setFilter(item)} data-testid={`button-filter-${item.toLowerCase().replaceAll(' ', '-')}`} className={`whitespace-nowrap rounded-full border px-3.5 py-2 text-[10px] ${filter === item ? 'border-[#dba4ff]/55 bg-[#dba4ff]/12 text-[#dfb1fa]' : 'border-white/[.1] text-[#8f8499] hover:bg-white/[.05]'}`}>{item}</button>)}</div>
    <GlassCard className="mb-6 flex items-center gap-4 p-4 sm:p-5"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#8fe8eb]/10 text-[#8fe8eb]"><UploadCloud size={18} /></div><div><div className="text-[12px] font-semibold text-[#e8dcef]">Make it yours</div><div className="mt-1 text-[10px] text-[#8d8296]">Each trend has an upload slot for your own reference video. Your examples stay in this local demo workspace.</div></div></GlassCard>
    <div id="trend-grid" className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{filtered.map((style, index) => <div key={style.id} className={`float-in-${Math.min(index + 1, 4)}`}><ReferenceStyleCard style={style} selected={false} onSelect={() => undefined} /></div>)}</div>
  </div>;
}

function Router() {
  return <Shell><ErrorBoundary resetKey={window.location.pathname}><Switch><Route path="/" component={Dashboard} /><Route path="/create" component={CreateStudioPage} /><Route path="/styles" component={TrendsPage} /><Route path="/projects" component={ProjectsPage} /><Route path="/preferences" component={PreferencesPage} /><Route path="/profile" component={ProfilePage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFoundPage} /></Switch></ErrorBoundary></Shell>;
}

function App() {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const notify = (message: string, tone: Toast['tone'] = 'info') => { const id = Date.now(); setToasts((current) => [...current.slice(-2), { id, message, tone }]); window.setTimeout(() => setToasts((current) => current.filter((toast) => toast.id !== id)), 3600); };
  return <QueryClientProvider client={queryClient}><TooltipProvider><ToastContext.Provider value={notify}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /><ToastStack toasts={toasts} dismiss={(id) => setToasts((current) => current.filter((toast) => toast.id !== id))} /></ToastContext.Provider></TooltipProvider></QueryClientProvider>;
}

export default App;